//! Income projection — a BAND, its assumptions written down, and a REFUSAL when the history is thin.
//!
//! A projection is the point where analysis stops describing and starts being acted on: it is what a
//! runway figure divides by, what a payoff schedule promises against, and what decides whether a
//! balance transfer is safe. So the failure mode is not inaccuracy — it is a single confident number
//! that hides how little it knows.
//!
//! Three commitments follow, and each is enforced here rather than left to the reader:
//!
//! 1. **A BAND, NEVER A POINT.** Low / expected / high, every month. The low is the one a plan is
//!    built on; the expected is the one a plan is *hoped* on.
//! 2. **THE BAND WIDENS WITH DISTANCE.** Month six is not as knowable as month one. A flat band
//!    asserts that it is, which is the specific lie that makes a twelve-month plan collapse in
//!    month four.
//! 3. **IT REFUSES.** Given two months of history it returns [`IncomeProjection::projectable`] false
//!    and no numbers — not a band of zeroes, which reads as "you will earn nothing" and is worse
//!    than saying nothing.
use crate::income::{IncomeAnalysis, IncomeSource};
use crate::money::{money, sum, Currency, Minor, Money};
use crate::txn::month_of;

pub(crate) use cadence_days::cadence_days;
pub use add_months::add_months;
pub(crate) use is_lapsed::is_lapsed;
pub(crate) use monthly_range::monthly_range;
pub use band_for::band_for;
pub use committable_monthly::committable_monthly;

#[derive(Debug, Clone, PartialEq)]
pub struct MonthBand {
    /// `YYYY-MM`.
    pub month: String,
    /// What the month looks like if everything that can reasonably go wrong does. Plan on this.
    pub low: Money,
    /// The median-driven figure. Hope on this.
    pub expected: Money,
    pub high: Money,
}

/// Why a source the analysis found is not in the projection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExclusionReason {
    Lapsed,
}

impl ExclusionReason {
    pub fn label(self) -> &'static str {
        match self {
            ExclusionReason::Lapsed => "lapsed",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct ExcludedSource {
    pub key: String,
    pub label: String,
    pub reason: ExclusionReason,
    pub last_seen: String,
    /// What it WOULD have contributed. Named so the size of the exclusion is visible.
    pub monthly_equivalent: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ProjectionTotal {
    pub low: Money,
    pub expected: Money,
    pub high: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct IncomeProjection {
    pub projectable: bool,
    /// Present ONLY when `projectable` is false, and it says what was missing.
    pub reason: Option<String>,
    /// Empty when not projectable — never a band of zeroes.
    pub months: Vec<MonthBand>,
    /// Absent when not projectable, so a caller cannot accidentally add zero into a runway.
    pub total: Option<ProjectionTotal>,
    /// Every judgement this projection made, in prose, for the reader to disagree with.
    pub assumptions: Vec<String>,
    pub excluded: Vec<ExcludedSource>,
    pub sources_used: usize,
}

pub struct ProjectionOptions<'a> {
    /// `YYYY-MM-DD` — what "now" is. Passed IN, never read from a clock.
    pub as_of: &'a str,
    /// How many months forward.
    pub months: usize,
    /// Fewest WHOLE months of history before a projection is honest. Below it, this refuses.
    pub min_months_observed: usize,
    /// A source unseen for this many of its own periods is treated as ended.
    pub lapse_factor: f64,
    /// How much the band widens per month out, as a fraction of the observed spread.
    pub drift_per_month: f64,
    /// Widening applied per month EVEN TO A PERFECTLY STEADY SOURCE, as a fraction of expected.
    /// Four months of an identical salary is not evidence that a salary cannot stop; a band that
    /// stayed pinned to the observed spread would say it is.
    pub floor_uncertainty: f64,
}

impl<'a> ProjectionOptions<'a> {
    /// The defaults the TypeScript kit applies when the caller supplies only `asOf`.
    pub fn new(as_of: &'a str) -> Self {
        ProjectionOptions { as_of, months: 6, min_months_observed: 3, lapse_factor: 2.5, drift_per_month: 0.15, floor_uncertainty: 0.02 }
    }
}

pub fn project_income(analysis: &IncomeAnalysis, currency: Currency, opts: &ProjectionOptions) -> IncomeProjection {
    let mut excluded: Vec<ExcludedSource> = Vec::new();
    let mut live: Vec<&IncomeSource> = Vec::new();
    for s in &analysis.sources {
        if is_lapsed(s, opts.as_of, opts.lapse_factor) {
            // A CONTRACT THAT ENDED IS NOT INCOME. Projecting a source last seen four months ago
            // forward for another six is the most expensive mistake this module can make, because
            // it is invisible: the total looks healthy and every downstream figure inherits money
            // that is not coming.
            excluded.push(ExcludedSource {
                key: s.key.clone(),
                label: s.label.clone(),
                reason: ExclusionReason::Lapsed,
                last_seen: s.last_seen.clone(),
                monthly_equivalent: s.monthly_equivalent,
            });
            continue;
        }
        live.push(s);
    }

    let refuse = |reason: String, excluded: Vec<ExcludedSource>| IncomeProjection {
        projectable: false,
        reason: Some(reason),
        months: Vec::new(),
        total: None,
        assumptions: Vec::new(),
        excluded,
        sources_used: 0,
    };

    if analysis.months_observed < opts.min_months_observed {
        let r = format!(
            "{} whole month(s) of history; {} are needed before a projection means anything",
            analysis.months_observed, opts.min_months_observed
        );
        return refuse(r, excluded);
    }
    if live.is_empty() {
        let r = if excluded.is_empty() {
            "no repeating income source was found".to_string()
        } else {
            let latest = excluded.iter().map(|e| e.last_seen.clone()).max().unwrap_or_default();
            format!("every income source has lapsed — the most recent receipt was {latest}")
        };
        return refuse(r, excluded);
    }

    let each: Vec<Money> = live.iter().map(|s| s.monthly_equivalent).collect();
    // Every source came from one analysis over one currency, so this cannot mismatch; falling back
    // to zero would be a silent wrong answer, so it refuses instead.
    let Ok(expected_money) = sum(&each, currency) else {
        return refuse("income sources are denominated in more than one currency, which this cannot add".to_string(), excluded);
    };
    let expected = expected_money.minor;
    let ranges: Vec<(Minor, Minor)> = live.iter().map(|s| monthly_range(s)).collect();
    let source_low: Minor = ranges.iter().map(|r| r.0).sum();
    let source_high: Minor = ranges.iter().map(|r| r.1).sum();

    // THE FLOOR HONOURS THE WORST MONTH THAT ACTUALLY HAPPENED. Summing each source's smallest
    // payment assumes every source paid — but a month where one simply did not pay is worse than
    // that sum, and it is the month a plan has to survive. Whichever is lower wins.
    let worst = analysis.worst_month.minor;
    let clamped = worst < source_low;
    let low_base = if clamped { worst } else { source_low };
    let high_base = source_high.max(expected);

    let start = month_of(opts.as_of).to_string();
    let mut bands: Vec<MonthBand> = Vec::new();
    for i in 0..opts.months {
        let widen = 1.0 + opts.drift_per_month * i as f64;
        let floor = opts.floor_uncertainty * (i + 1) as f64 * expected as f64;
        let low = (expected as f64 - ((expected - low_base) as f64 * widen + floor)).round().max(0.0) as Minor;
        let high = (expected as f64 + ((high_base - expected) as f64 * widen + floor)).round() as Minor;
        bands.push(MonthBand {
            // The month `as_of` falls in is already partly spent, so the projection starts at the NEXT one.
            month: add_months(&start, i as i64 + 1),
            low: money(low, currency),
            expected: money(expected, currency),
            high: money(high, currency),
        });
    }

    let mut assumptions = vec![
        format!("Projected from {} whole month(s) of history across {} repeating source(s).", analysis.months_observed, live.len()),
        "Expected is each source's MEDIAN receipt scaled to a month, so one unusually large payment does not move it.".to_string(),
        format!(
            "The band widens {}% of the observed spread per month, plus {}% of expected — month {} is less certain than month 1, and the numbers say so.",
            (opts.drift_per_month * 100.0).round(),
            (opts.floor_uncertainty * 100.0).round(),
            opts.months
        ),
        format!("Starts at {}: the month containing {} is already partly spent.", bands.first().map(|b| b.month.as_str()).unwrap_or(""), opts.as_of),
    ];
    if clamped {
        assumptions.push(
            "The floor uses the worst whole month observed rather than the sum of each source's smallest payment — a month where a source did not pay at all is worse than a month where it paid little.".to_string(),
        );
    }
    if !analysis.one_off.is_empty() {
        let amounts: Vec<Money> = analysis.one_off.iter().map(|t| t.amount).collect();
        if let Ok(total) = sum(&amounts, currency) {
            assumptions.push(format!(
                "{} one-off receipt(s) totalling {} minor units are NOT projected — a refund is not income you can plan on receiving again.",
                analysis.one_off.len(),
                total.minor
            ));
        }
    }
    if !excluded.is_empty() {
        let names: Vec<String> = excluded.iter().map(|e| format!("{} (last seen {})", e.label, e.last_seen)).collect();
        assumptions.push(format!("{} source(s) excluded as lapsed: {}.", excluded.len(), names.join(", ")));
    }

    let lows: Vec<Money> = bands.iter().map(|b| b.low).collect();
    let exps: Vec<Money> = bands.iter().map(|b| b.expected).collect();
    let highs: Vec<Money> = bands.iter().map(|b| b.high).collect();
    let total = match (sum(&lows, currency), sum(&exps, currency), sum(&highs, currency)) {
        (Ok(low), Ok(expected), Ok(high)) => Some(ProjectionTotal { low, expected, high }),
        _ => None,
    };

    IncomeProjection { projectable: true, reason: None, months: bands, total, assumptions, excluded, sources_used: live.len() }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::income::IncomeCadence;
    use crate::income::{analyse_income, IncomeOptions};
    use crate::money::usd;
    use crate::txn::Txn;

    // SYNTHETIC FIXTURES ONLY.
    fn t(date: &str, description: &str, minor: Minor) -> Txn {
        Txn { account: "a".to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn project(rows: &[Txn], as_of: &str, months: usize) -> IncomeProjection {
        let a = analyse_income(rows, Currency::USD, &IncomeOptions::default());
        project_income(&a, Currency::USD, &ProjectionOptions { months, ..ProjectionOptions::new(as_of) })
    }

    #[test]
    fn month_arithmetic_steps_backwards_over_a_year_boundary() {
        // Measured against the TypeScript. `%` on a negative is negative in both languages, so a
        // naive modulo puts January minus one month on month -1 rather than December.
        assert_eq!(add_months("2026-01", 1), "2026-02");
        assert_eq!(add_months("2026-01", -1), "2025-12");
        assert_eq!(add_months("2026-01", 12), "2027-01");
        assert_eq!(add_months("2026-01", -13), "2024-12");
        assert_eq!(add_months("2026-12", 1), "2027-01");
        assert_eq!(add_months("2026-03", -5), "2025-10");
        assert_eq!(add_months("2026-06", 0), "2026-06");
    }

    #[test]
    fn a_steady_salary_still_widens_because_a_salary_can_stop() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-29", "2026-06-30", "2026-07-31"]
            .iter()
            .map(|d| t(d, "ACME PAYROLL", 400_000))
            .collect();
        let p = project(&rows, "2026-07-15", 3);
        assert!(p.projectable);
        assert_eq!(p.sources_used, 1);
        let got: Vec<(&str, i64, i64, i64)> = p.months.iter().map(|b| (b.month.as_str(), b.low.minor, b.expected.minor, b.high.minor)).collect();
        // Seven identical payments and the band STILL opens 2% of expected per month. That is the
        // floorUncertainty doing its job: a perfect history is not evidence of a perfect future.
        assert_eq!(got, vec![("2026-08", 392_000, 400_000, 408_000), ("2026-09", 384_000, 400_000, 416_000), ("2026-10", 376_000, 400_000, 424_000)]);
        assert_eq!(p.total.as_ref().unwrap().low.minor, 1_152_000);
        assert_eq!(p.total.as_ref().unwrap().expected.minor, 1_200_000);
        assert_eq!(p.total.as_ref().unwrap().high.minor, 1_248_000);
        // The commitment figure is the FURTHEST month's low, not the nearest.
        assert_eq!(committable_monthly(&p).unwrap().minor, 376_000);
        assert_eq!(band_for(&p, "2026-09").unwrap().low.minor, 384_000);
        assert!(band_for(&p, "2026-12").is_none(), "outside the horizon is absent, not zero");
    }

    #[test]
    fn a_lumpy_income_reaches_a_floor_of_zero_and_says_so_rather_than_flattering_itself() {
        let rows: Vec<Txn> = [("2026-01-05", 300_000), ("2026-02-04", 50_000), ("2026-03-06", 420_000), ("2026-04-05", 120_000), ("2026-05-05", 260_000), ("2026-06-04", 310_000)]
            .iter()
            .map(|(d, m)| t(d, "CLIENT INVOICE", *m))
            .collect();
        let p = project(&rows, "2026-06-20", 4);
        let got: Vec<(&str, i64, i64, i64)> = p.months.iter().map(|b| (b.month.as_str(), b.low.minor, b.expected.minor, b.high.minor)).collect();
        assert_eq!(
            got,
            vec![("2026-07", 44_400, 280_000, 425_600), ("2026-08", 4_300, 280_000, 452_200), ("2026-09", 0, 280_000, 478_800), ("2026-10", 0, 280_000, 505_400)]
        );
        // By month three the honest floor is nothing. A point estimate of 280000 would have said
        // this person can commit to a payment they might not be able to make.
        assert_eq!(committable_monthly(&p).unwrap().minor, 0);
    }

    #[test]
    fn thin_history_refuses_rather_than_returning_a_band_of_zeroes() {
        let rows: Vec<Txn> = ["2026-05-31", "2026-06-30", "2026-07-31"].iter().map(|d| t(d, "ACME PAYROLL", 400_000)).collect();
        let p = project(&rows, "2026-07-15", 3);
        assert!(!p.projectable);
        assert_eq!(p.reason.as_deref(), Some("1 whole month(s) of history; 3 are needed before a projection means anything"));
        assert!(p.months.is_empty(), "no numbers at all");
        // A band of zeroes reads as "you will earn nothing"; ABSENT reads as "this does not know".
        assert!(p.total.is_none(), "the total is ABSENT so a runway cannot add zero into itself");
        assert!(committable_monthly(&p).is_none());
        assert!(p.assumptions.is_empty(), "a refusal makes no assumptions to disagree with");
    }

    #[test]
    fn a_contract_that_ended_is_excluded_and_the_size_of_the_exclusion_is_named() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-29"].iter().map(|d| t(d, "OLD CONTRACT", 400_000)).collect();
        let p = project(&rows, "2026-09-01", 3);
        assert!(!p.projectable, "every source lapsed, so there is nothing to project");
        assert_eq!(p.reason.as_deref(), Some("every income source has lapsed — the most recent receipt was 2026-05-29"));
        assert_eq!(p.excluded.len(), 1);
        assert_eq!(p.excluded[0].reason, ExclusionReason::Lapsed);
        assert_eq!(p.excluded[0].last_seen, "2026-05-29");
        // What it WOULD have contributed, so the hole is visible rather than merely missing.
        assert_eq!(p.excluded[0].monthly_equivalent.minor, 400_000);
    }

    #[test]
    fn lapse_is_measured_in_the_sources_own_periods_not_a_fixed_window() {
        let weekly = IncomeSource {
            key: "gig".into(), label: "GIG".into(), account: "a".into(), cadence: IncomeCadence::Weekly,
            typical: usd(40_000), low: usd(40_000), high: usd(40_000), occurrences: 8,
            first_seen: "2026-01-02".into(), last_seen: "2026-02-20".into(), consistency: 1.0,
            stability: crate::income::Stability::Steady, monthly_equivalent: usd(173_333),
        };
        let monthly = IncomeSource { cadence: IncomeCadence::Monthly, ..weekly.clone() };
        // 25 days on: a WEEKLY source is long gone (7 * 2.5 = 17.5), a MONTHLY one is not yet due
        // to worry (30.4 * 2.5 = 76). A single fixed window would call both the same.
        assert!(is_lapsed(&weekly, "2026-03-17", 2.5));
        assert!(!is_lapsed(&monthly, "2026-03-17", 2.5));
        // An unclassifiable cadence has no period to measure against, so it is never called lapsed.
        let irregular = IncomeSource { cadence: IncomeCadence::Irregular, ..weekly.clone() };
        assert!(!is_lapsed(&irregular, "2030-01-01", 2.5));
    }

    #[test]
    fn the_assumptions_are_written_down_for_the_reader_to_disagree_with() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-29", "2026-06-30", "2026-07-31"]
            .iter()
            .map(|d| t(d, "ACME PAYROLL", 400_000))
            .collect();
        let p = project(&rows, "2026-07-15", 3);
        assert_eq!(p.assumptions.len(), 4, "measured against the TypeScript");
        assert!(p.assumptions.iter().any(|a| a.contains("MEDIAN")), "the median choice is stated");
        assert!(p.assumptions.iter().any(|a| a.contains("already partly spent")), "the start month is justified");
        assert!(p.assumptions.iter().any(|a| a.contains("15% of the observed spread")), "the widening rate is stated");
    }

    #[test]
    fn nothing_to_project_is_a_refusal_that_names_which_emptiness_it_is() {
        let a = analyse_income(&[t("2026-01-05", "RENT LANDLORD LLC", -120_000)], Currency::USD, &IncomeOptions::default());
        let p = project_income(&a, Currency::USD, &ProjectionOptions::new("2026-07-15"));
        assert!(!p.projectable);
        // Zero months of history is a DIFFERENT problem from having sources that all lapsed, and
        // the reason says which — one is answered by waiting, the other by finding work.
        assert_eq!(p.reason.as_deref(), Some("0 whole month(s) of history; 3 are needed before a projection means anything"));
    }
}
